-- ── Triggers ────────────────────────────────────────────────────────────────
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE TRIGGER chapters_check_sibling_position AFTER INSERT OR UPDATE OF group_id, "position" ON chapters FOR EACH ROW EXECUTE FUNCTION check_structure_sibling_position();
CREATE TRIGGER chapters_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON chapters FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER chapters_protect_placement BEFORE UPDATE OF group_id, "position" ON chapters FOR EACH ROW EXECUTE FUNCTION protect_structure_placement();
CREATE TRIGGER manuscript_groups_check_sibling_position AFTER INSERT OR UPDATE OF parent_group_id, "position" ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION check_structure_sibling_position();
CREATE TRIGGER manuscript_groups_forbid_cycle BEFORE INSERT OR UPDATE OF parent_group_id ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_group_cycle();
CREATE TRIGGER manuscript_groups_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER manuscript_groups_protect_placement BEFORE UPDATE OF parent_group_id, "position" ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION protect_structure_placement();
CREATE TRIGGER profiles_protect_billing_columns BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_billing_columns();
CREATE TRIGGER profiles_protect_is_admin BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_is_admin();
CREATE TRIGGER projects_protect_word_count BEFORE UPDATE OF word_count ON projects FOR EACH ROW EXECUTE FUNCTION protect_project_word_count();
CREATE TRIGGER trg_project_manuscript AFTER INSERT ON projects FOR EACH ROW EXECUTE FUNCTION create_project_manuscript();
CREATE TRIGGER scene_version_trigger BEFORE UPDATE ON scenes FOR EACH ROW EXECUTE FUNCTION increment_scene_version();
CREATE TRIGGER scenes_detach_writing_sessions BEFORE DELETE ON scenes FOR EACH ROW EXECUTE FUNCTION detach_scene_writing_sessions();
CREATE TRIGGER scenes_fill_manuscript_id BEFORE INSERT ON scenes FOR EACH ROW EXECUTE FUNCTION fill_scene_manuscript_id();
CREATE TRIGGER scenes_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON scenes FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER scenes_refresh_project_word_count AFTER INSERT OR DELETE OR UPDATE OF word_count, chapter_id ON scenes FOR EACH ROW EXECUTE FUNCTION refresh_project_word_count();
CREATE TRIGGER trg_scene_updated AFTER UPDATE ON scenes FOR EACH ROW EXECUTE FUNCTION bump_project_updated_at();
CREATE TRIGGER user_pricing_entitlements_touch_updated_at BEFORE UPDATE ON user_pricing_entitlements FOR EACH ROW EXECUTE FUNCTION touch_pricing_entitlement_updated_at();
CREATE TRIGGER workspace_collection_entries_forbid_project_reassignment BEFORE UPDATE OF project_id ON workspace_collection_entries FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER workspace_collection_entries_freeze_collection BEFORE UPDATE OF collection_id ON workspace_collection_entries FOR EACH ROW EXECUTE FUNCTION freeze_workspace_entry_collection();
CREATE TRIGGER workspace_collection_entries_stamp BEFORE INSERT OR UPDATE ON workspace_collection_entries FOR EACH ROW EXECUTE FUNCTION stamp_workspace_document();
CREATE TRIGGER workspace_collections_forbid_project_reassignment BEFORE UPDATE OF project_id ON workspace_collections FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER workspace_collections_place_new AFTER INSERT ON workspace_collections FOR EACH ROW EXECUTE FUNCTION place_new_workspace_object();
CREATE TRIGGER workspace_collections_stamp BEFORE INSERT OR UPDATE ON workspace_collections FOR EACH ROW EXECUTE FUNCTION stamp_workspace_folder();
CREATE TRIGGER workspace_documents_forbid_project_reassignment BEFORE UPDATE OF project_id ON workspace_documents FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER workspace_documents_place_new AFTER INSERT ON workspace_documents FOR EACH ROW EXECUTE FUNCTION place_new_workspace_object();
CREATE TRIGGER workspace_documents_stamp BEFORE INSERT OR UPDATE ON workspace_documents FOR EACH ROW EXECUTE FUNCTION stamp_workspace_document();
CREATE TRIGGER workspace_folders_forbid_project_reassignment BEFORE UPDATE OF project_id ON workspace_folders FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER workspace_folders_place_new AFTER INSERT ON workspace_folders FOR EACH ROW EXECUTE FUNCTION place_new_workspace_object();
CREATE TRIGGER workspace_folders_stamp BEFORE INSERT OR UPDATE ON workspace_folders FOR EACH ROW EXECUTE FUNCTION stamp_workspace_folder();
CREATE TRIGGER workspace_nodes_check_parent BEFORE INSERT OR UPDATE OF parent_node_id ON workspace_nodes FOR EACH ROW EXECUTE FUNCTION check_workspace_node_parent();
CREATE TRIGGER workspace_nodes_forbid_project_reassignment BEFORE UPDATE OF project_id ON workspace_nodes FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER workspace_nodes_freeze_target BEFORE UPDATE OF target_type, document_id, folder_id, collection_id ON workspace_nodes FOR EACH ROW EXECUTE FUNCTION freeze_workspace_node_target();

