  ('008', '008_future_letters.sql', null, 'historical — contained in the baseline; never re-run'),
  ('009', '009_pricing_cohorts.sql', null, 'historical — contained in the baseline; never re-run (contains a one-time backfill)'),
  ('010', '010_analytics_excluded_users.sql', null, 'historical — contained in the baseline; never re-run'),
  ('011', '011_account_word_limit.sql', null, 'historical — contained in the baseline; never re-run'),
  ('012', '012_fix_bump_project_updated_at.sql', null, 'historical — contained in the baseline; never re-run'),
  ('013', '013_schema_migrations_ledger.sql', null, 'ledger created'),
  ('014', '014_assert_production_baseline.sql', null, 'baseline assertions passed: production-only columns, FK cascades, writing_sessions indexes, triggers, save-path RPC contracts, manuscript RLS policy set'),
  ('015', '015_rune2_manuscript_foundation.sql', null, 'Rune 2.0 manuscript foundation on an empty database: manuscripts, chapters.manuscript_id, scenes (replaces pages), writing_sessions.scene_id, Scene save RPCs, no canonical behavior'),
  ('016', '016_scene_structure_rpcs.sql', null, 'Rune 2.0 Scene structure: insert_unplaced_scene_checked (free-limit-checked Unplaced creation), reorder_chapter_scenes (atomic, validated Scene reorder)'),
  ('017', '017_atomic_scene_move.sql', null, 'Rune 2.0 atomic Scene move: move_scene (Chapter/Unplaced, one transaction under the per-account lock, recomputes the ordered total)'),
  ('018', '018_atomic_scene_creation.sql', null, 'Rune 2.0 atomic placed-Scene creation: insert_scene_checked validates the Chapter and appends under the per-account lock (p_position accepted, ignored)'),
  ('019', '019_creation_path_hardening.sql', null, 'Rune 2.0 creation hardening: create_chapter_checked (Chapter + first Scene atomically); Scene INSERT only through the SECURITY DEFINER creation RPCs; unique deferrable (chapter_id, position)'),
  ('020', '020_manuscript_totals.sql', null, 'Rune 2.0 manuscript totals: projects.word_count maintained by trigger (ordered placed-Scene total); Chapter INSERT only through the SECURITY DEFINER creation RPCs; unique deferrable (manuscript_id, position)'),
  ('021', '021_project_lifecycle_hardening.sql', null, 'Rune 2.0 project lifecycle: create_project_checked (Project + Manuscript + Chapter 1 + Scene 1 atomically, deduplicated by creation_request_id); no client INSERT on projects or write of projects.word_count; Chapter deletion (delete_chapter) moves its Scenes to Unplaced, FK no longer cascades'),
  ('022', '022_manuscript_groups.sql', null, 'Rune 2.0 Manuscript Groups (recursive, no prose) and one sibling ordering model for Groups + Chapters (create/delete/move RPCs, cycle-proof); unique Unplaced Scene order; deleting a Scene keeps its writing history (scene_id set null, merged into Project-level history)'),
  ('023', '023_workspace_pages.sql', null, 'Workspace Pages (workspace_documents): per-Project freeform documents, content-versioned, RLS by Project owner, no client DELETE'),
  ('024', '024_workspace_tree.sql', null, 'Workspace tree: workspace_folders + workspace_nodes (one canonical node per Page/Folder), atomic create/move/delete-empty-folder RPCs, top-level backfill of existing Pages'),
  ('025', '025_workspace_collections.sql', null, 'Workspace Collections + Entries: workspace_collections (one canonical node each), workspace_collection_entries (content-versioned, RLS by Project owner, no client DELETE), empty-only Collection deletion');
